add_action( 'woocommerce_before_account_orders', 'perfectpixel_my_orders_status_links' );
add_filter( 'woocommerce_my_account_my_orders_query', 'perfectpixel_my_orders_status_query' );
add_filter( 'woocommerce_get_endpoint_url', 'perfectpixel_my_orders_status_pagination', 10, 2 );

function perfectpixel_my_orders_current_status() {
	$status = isset( $_GET['order_status'] ) ? sanitize_key( $_GET['order_status'] ) : '';
	return array_key_exists( 'wc-' . $status, wc_get_order_statuses() ) ? $status : '';
}

function perfectpixel_my_orders_status_links() {
	$used = array();
	foreach ( wc_get_orders( array( 'customer' => get_current_user_id(), 'limit' => 200 ) ) as $order ) {
		$used[ $order->get_status() ] = true;
	}
	if ( count( $used ) < 2 ) {
		return;
	}
	$base    = wc_get_account_endpoint_url( 'orders' );
	$current = perfectpixel_my_orders_current_status();
	$links   = array( '' === $current ? '<strong>' . esc_html( '{{orders_filter_all_label}}' ) . '</strong>' : '<a href="' . esc_url( $base ) . '">' . esc_html( '{{orders_filter_all_label}}' ) . '</a>' );
	foreach ( wc_get_order_statuses() as $key => $label ) {
		$status = substr( $key, 3 );
		if ( isset( $used[ $status ] ) ) {
			$links[] = $status === $current ? '<strong>' . esc_html( $label ) . '</strong>' : '<a href="' . esc_url( add_query_arg( 'order_status', $status, $base ) ) . '">' . esc_html( $label ) . '</a>';
		}
	}
	echo '<p class="perfectpixel-orders-filter">' . implode( ' &middot; ', $links ) . '</p>';
}

function perfectpixel_my_orders_status_query( $args ) {
	$status = perfectpixel_my_orders_current_status();
	if ( $status ) {
		$args['status'] = array( $status );
	}
	return $args;
}

function perfectpixel_my_orders_status_pagination( $url, $endpoint ) {
	$status = perfectpixel_my_orders_current_status();
	return ( 'orders' === $endpoint && $status ) ? add_query_arg( 'order_status', $status, $url ) : $url;
}
